!function(r){function e(e){for(var t,a,o=e[0],i=e[1],c=e[2],s=0,g=[];s<o.length;s++)a=o[s],Object.prototype.hasOwnProperty.call(p,a)&&p[a]&&g.push(p[a][0]),p[a]=0;for(t in i)Object.prototype.hasOwnProperty.call(i,t)&&(r[t]=i[t]);for(d&&d(e);g.length;)g.shift()();return m.push.apply(m,c||[]),n()}function n(){for(var r,e=0;e<m.length;e++){for(var n,a=m[e],o=!0,i=1;i<a.length;i++)n=a[i],0!==p[n]&&(o=!1);o&&(m.splice(e--,1),r=t(t.s=a[0]))}return r}function t(e){if(a[e])return a[e].exports;var n=a[e]={i:e,l:!1,exports:{}};return r[e].call(n.exports,n,n.exports,t),n.l=!0,n.exports}var a={},p={47:0},m=[];t.m=r,t.c=a,t.d=function(r,e,n){t.o(r,e)||Object.defineProperty(r,e,{enumerable:!0,get:n})},t.r=function(r){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(r,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(r,"__esModule",{value:!0})},t.t=function(r,e){if(1&e&&(r=t(r)),8&e)return r;if(4&e&&"object"==typeof r&&r&&r.__esModule)return r;var n=Object.create(null);if(t.r(n),Object.defineProperty(n,"default",{enumerable:!0,value:r}),2&e&&"string"!=typeof r)for(var a in r)t.d(n,a,function(e){return r[e]}.bind(null,a));return n},t.n=function(r){var e=r&&r.__esModule?function(){return r.default}:function(){return r};return t.d(e,"a",e),e},t.o=function(r,e){return Object.prototype.hasOwnProperty.call(r,e)},t.p="";var o=window.webpackJsonp=window.webpackJsonp||[],i=o.push.bind(o);o.push=e,o=o.slice();for(var c=0;c<o.length;c++)e(o[c]);var d=i;m.push([220,0]),n()}({220:function(r,e,n){"use strict";n.r(e);var t=n(0);Object(t.a)("de","army",n(221),n(1))},221:function(r){r.exports=JSON.parse('{"category":[{"name":"德国","link":"de_shortcut"},{"name":"陆战武器","link":"de_army"},{"name":"火炮","link":"de_army#de_army_cannon"}],"model":"德军迫击炮","description":"<p>二战期间，德军使用的迫击炮主要有50mm口径的GrW36型和80mm口径的GrW34型（含基于GrW34型上改短、主要供伞兵使用的80mm口径kz 8cm GrW42型），以及仿制苏联PM38型的120mm口径GrW42型。其中GrW36型因火力太弱，射程太短，后逐步被80mm口径的GrW42型替代。二战期间，因为德军有大量反坦克炮，以及数量较多的作地面火力支援的轻步兵炮与小口径高射炮，因此没有专门去研发大口径的重型迫击炮，对迫击炮的研发与运用是不够重视的。</p><p>作为步兵随身携带作战的一种重武器，德军的迫击炮主要装备给班排单位，在战场最前线作近距离重火力支援；120重迫击炮服役后，才有连属迫击炮。二战爆发时，德军每个野战步兵师装备有50mm迫击炮90门（平均每个步兵团装备27门），81mm迫击炮54门（平均每团装备18门）。</p><p>配有光学瞄准镜的36型（50mm）迫击炮在1939年至1943年间共生产了25842门；GrW34型（实际口径81.4mm）迫击炮的生产一直到二战结束，产量为71630门；改短后的kz 8cm GrW42型（实际口径81.4mm）迫击炮只在1943年生产了1591门；而仿制的GrW42型（120mm口径）迫击炮生产了8461门（不含缴获的苏军同口径迫击炮）。</p>","part1title":"","part1description":"","part1content":[{"image":"imgs/de/army/de_army_cannonMortar_11.jpg","description":"<h6>GrW36型（50mm）迫击炮</h6><p></p><p>技术数据：</p><p>整炮重量：14公斤；</p><p>炮管长度：463毫米；口径：50毫米；</p><p>最大射击仰角 42°至90° ；最大回旋角度 33°至45°；</p><p>炮弹重量：0.9公斤 ，出膛初速：75米/秒，发射速率 15-25发/每分钟；</p><p>最大射程 520米（有效射程范围：50米～510米）。</p>","caption":""},{"image":"imgs/de/army/de_army_cannonMortar_12.jpg","description":"<h6>GrW34型（80mm）迫击炮</h6><p></p><p>技术数据：</p><p>整炮重量：56.7公斤；</p><p>炮管长度：1143毫米；口径：81.4毫米；</p><p>最大射击仰角 40°至90° ，最大回旋角度 9°至15° ；</p><p>炮弹重量：3.5公斤，出膛初速：172米/秒（34型炮弹），发射速率 15-25发/每分钟；</p><p>最大射程 2400米。</p>","caption":""},{"image":"imgs/de/army/de_army_cannonMortar_13.jpg","description":"<h6>GrW42型（120mm）迫击炮</h6><p></p><p>技术数据：</p><p>整炮重量：285公斤；</p><p>炮管长度：1865毫米；口径：120毫米；</p><p>炮弹重量：15.8公斤，出膛初速：283米/秒（WGr42型迫击炮弹）；</p><p>最大射程 6050米。</p>","caption":""}],"part2title":"战场上的德军迫击炮","part2description":"","part2content":[{"image":"imgs/de/army/de_army_cannonMortar_21.jpg","description":"二战东线苏联战场，一名德国山地师的士兵正向50mm GrW36迫击炮装填炮弹。注：迫击炮是步兵近距离支援作战的曲射型火炮，往往在可目视目标的距离内使用。其主要结构可分三部分：炮管、炮架和底座，迫击炮一般配有简单的观瞄设备。弹丸是从炮口直接放入，靠自重沿身管内壁滑落到炮管底部，通过炮管底部的撞针击发炮弹。迫击炮主要是对人员杀伤用，对轻装甲目标以及敞篷车辆有一定威胁。","caption":""},{"image":"imgs/de/army/de_army_cannonMortar_22.jpg","description":"二战东线苏联战场，一名德国武装党卫军士兵正在前线战壕内给50mm GrW36迫击炮装弹发射。这种小口径迫击炮轻巧，便于携带，主要是为步兵班、排所用，但由于射击不准确，因此无法遏制有压倒性人数进攻的苏军。","caption":""},{"image":"imgs/de/army/de_army_cannonMortar_23.jpg","description":"二战东线苏联战场，两名德国武装党卫军士兵正在使用50mm GrW36迫击炮进行战斗。德军的50mm GrW36迫击炮一般会配备两名炮手。","caption":""},{"image":"imgs/de/army/de_army_cannonMortar_24.jpg","description":"二战东线苏联战场，德军士兵将50毫米迫击炮放置在一个坟墓旁边作掩护进行射击，炮手为了避免炮弹出膛瞬间的冲击已将头埋下。在炮前的金属弹药箱中装有10枚炮弹，这种炮弹很轻，长度还小于德军的M24手榴弹，杀伤力不大。50mm GrW36迫击炮由于隐蔽性好，便于单兵携带，威力射程也比步兵班中的其它武器强，因此在1943年停止装备后，仍有一些保留并坚持战斗到二战结束。","caption":""},{"image":"imgs/de/army/de_army_cannonMortar_25.jpg","description":"二战东线冬季苏联战场，一个德军50mm GrW36迫击炮班士兵正在雪地中进行发射准备。二战初期，德军每个步兵排都会有一个专门携带一门GrW36迫击炮的炮班。","caption":""},{"image":"imgs/de/army/de_army_cannonMortar_26.jpg","description":"德军80mm GrW34迫击炮班士兵正在进行装弹发射。二战期间，80mm GrW34是德军步兵使用的主流迫击炮。GrW34迫击炮的炮组一般为四人，由于火炮性能较好，加上德军炮兵训练有素，实战中威力不错，只是因为德军炮兵部队过于强势，迫击炮的作用显得不够突出，所以对于迫击炮的重视程度，德军明显不如苏军。","caption":""},{"image":"imgs/de/army/de_army_cannonMortar_27.jpg","description":"德军80mm GrW34迫击炮班士兵准备发射烟雾弹以掩护步兵突击。80毫米的高爆弹和烟雾弹具有相同的重量，并且具有相同的弹道，因此不必重新计算射击数据；其烟雾弹最大有效范围为1900米，最小范围为60米。","caption":""},{"image":"imgs/de/army/de_army_cannonMortar_28.jpg","description":"二战东线苏联战场，隐蔽在树林中的一个德军80mm GrW34迫击炮班士兵正向苏军开火，由于GrW34迫击炮火力猛烈，射击精准，射速和射程也都比较好，因此能为德军步兵提供有效的火力支援。阵地上的铁制弹药箱有的已空，有的还装有炮弹；另外，由于是在前线作战，炮班士兵都配备有自卫用的手枪。","caption":""},{"image":"imgs/de/army/de_army_cannonMortar_29.jpg","description":"二战东线苏联战场，在战斗空隙，德军一个80毫米GrW34迫击炮班士兵正在战壕中休息。这处炮位中有两个装有不同类型炮弹的铁制弹药箱，80毫米GrW34迫击炮所配备的炮弹除了34型高爆杀伤弹外，还有烟雾弹等，此外还有一种装有长杆引信的38和39型空爆弹，这种装有长杆引信的炮弹能在距离地面一定高度的空中爆炸，具有更大的杀伤力。","caption":""},{"image":"imgs/de/army/de_army_cannonMortar_30.jpg","description":"二战早期东线战场，战斗中，德军一个80毫米GrW34迫击炮班士兵正在将炮弹放入炮筒进行发射。这些士兵还穿着较早发行的绿色带领上衣。其中一名的衣袖上还佩有一个燕尾V字形的徽章布，证明这是一个服役期不少于6年的老兵。","caption":""},{"image":"imgs/de/army/de_army_cannonMortar_31.jpg","description":"德军一门正准备发射的80毫米kz 8cm GrW42迫击炮，这型炮是用80毫米GrW34迫击炮改短的，炮管长度只有747毫米，炮重也减轻为26公斤。最初，这种短炮筒的GrW42型（实际口径为81.4mm）迫击炮是供伞兵使用的，后来也用来替换射程短的LeGrW36型（50mm）迫击炮。但生产数量只有1500多门。","caption":""},{"image":"imgs/de/army/de_army_cannonMortar_32.jpg","description":"绘画：东线战场上德军一个120毫米口径GrW42迫击炮阵地，炮兵正在装弹发射，120mm迫击炮由于体型较大，为了隐蔽，需要有一个深坑掩体。由于此炮威力大，因此深受德军步兵的喜爱。","caption":""}]}')}});